const RENDER_HOME_CACHE_VERSION = "v2";
const RENDER_HOME_CACHE_PREFIX = `caxl_render_home_${RENDER_HOME_CACHE_VERSION}_site_`;

function getRenderHomeCache(site) {
  if (!IS_RENDER) return "";
  try {
    return localStorage.getItem(RENDER_HOME_CACHE_PREFIX + site) || "";
  } catch (error) {
    return "";
  }
}

function setRenderHomeCache(site, html) {
  if (!IS_RENDER || !html) return;
  try {
    localStorage.setItem(RENDER_HOME_CACHE_PREFIX + site, html);
  } catch (error) {
    /* 缓存失败不影响首页正常加载 */
  }
}

function restoreRenderHomeCache() {
  if (!IS_RENDER) return;
  [1, 2, 3].forEach(site => {
    const box = document.getElementById(`home-site-${site}`);
    if (!box) return;
    const cached = getRenderHomeCache(site);
    if (cached) {
      box.innerHTML = cached;
    } else {
      box.innerHTML = "";
    }
  });
}

