const renderStaticPrefetchCache = new Set();

function prefetchRenderStaticLinks(limit = 8) {
  if (!IS_RENDER) return;

  const links = Array.from(document.querySelectorAll('a[href^="/fofa/"]'));
  let count = 0;

  for (const link of links) {
    if (count >= limit) break;

    const href = String(link.getAttribute("href") || "").trim();
    if (!href || renderStaticPrefetchCache.has(href)) continue;

    renderStaticPrefetchCache.add(href);
    count += 1;

    fetch(href, {
      method: "GET",
      credentials: "same-origin",
      cache: "force-cache"
    }).catch(() => {});
  }
}

function scheduleRenderStaticPrefetch() {
  if (!IS_RENDER) return;

  const run = () => prefetchRenderStaticLinks(8);

  if ("requestIdleCallback" in window) {
    requestIdleCallback(run, { timeout: 1500 });
  } else {
    setTimeout(run, 300);
  }
}

const renderPostPrefetchCache = new Set();
const renderPostDataCache = new Map();

function prefetchRenderPosts(limit = 6) {
  if (!IS_RENDER) return;

  const links = Array.from(document.querySelectorAll('a[href^="#/"]'));
  const targets = [];

  for (const link of links) {
    const href = String(link.getAttribute("href") || "");
    const match = href.match(/^#\/([123])\/(\d+)$/);
    if (!match) continue;

    const site = match[1];
    const tid = match[2];
    const key = `${site}:${tid}`;

    if (renderPostPrefetchCache.has(key)) continue;

    const rect = link.getBoundingClientRect();
    const visible =
      rect.bottom >= 0 &&
      rect.top <= (window.innerHeight || document.documentElement.clientHeight) * 1.5;

    if (!visible && targets.length >= limit) continue;

    renderPostPrefetchCache.add(key);
    targets.push({ site, tid });

    if (targets.length >= limit) break;
  }

  targets.forEach(({ site, tid }) => {
    fetch(`${API_BASE}/api/post.php?s=${encodeURIComponent(site)}&tid=${encodeURIComponent(tid)}`, {
      credentials: "same-origin",
      cache: "force-cache"
    })
      .then(response => response.ok ? response.json() : null)
      .then(data => {
        if (data && data.ok) {
          renderPostDataCache.set(`${site}:${tid}`, data);
        }
      })
      .catch(() => {});
  });
}

function scheduleRenderPostPrefetch() {
  if (!IS_RENDER) return;
  const run = () => prefetchRenderPosts(6);

  if ("requestIdleCallback" in window) {
    requestIdleCallback(run, { timeout: 1200 });
  } else {
    setTimeout(run, 250);
  }
}

function router() { const route = getRoute(); const postMatch = route.path.match(/^#\/([123])\/(\d+)$/); if (postMatch) { renderPost(Number(postMatch[1]), postMatch[2]); return; } const dirMatch = route.path.match(/^#\/([123])\/f\/(\d+)$/); if (dirMatch) { renderDirectory(Number(dirMatch[1]), dirMatch[2]); setTimeout(scheduleRenderPostPrefetch, 400); return; } const siteMatch = route.path.match(/^#\/([123])\/?$/); if (siteMatch) { renderSite(Number(siteMatch[1])); setTimeout(scheduleRenderPostPrefetch, 400); return; } renderHome(); setTimeout(scheduleRenderPostPrefetch, 400); } window.addEventListener("hashchange", router); if (document.readyState === "loading") { document.addEventListener("DOMContentLoaded", initGlobalTools, { once: true }); } else { initGlobalTools(); } router();
